function stats(){const d=allDepths(state.people);return {people:state.people.length,levels:state.people.length?Math.max(...Object.values(d))+1:0,teams:new Set(state.people.map(p=>p.dept).filter(Boolean)).size}}
function validPeople(people){
 if(!Array.isArray(people)||!people.length)throw Error('No employee records found.');
 if(people.length>10000)throw Error('A project can contain at most 10,000 positions in this edition.');
 const byId=new Map();for(const p of people){if(!p.id||!p.name)throw Error('Every position requires an Employee ID and Full Name.');if(byId.has(p.id))throw Error('Duplicate Employee ID: '+p.id);if(p.secondaryManager===p.id&&p.secondaryManager)throw Error('A position cannot be its own secondary manager: '+p.id);byId.set(p.id,p)}
 const color=new Map();for(const p of people){if(color.get(p.id)===2)continue;let chain=[],cur=p;while(cur&&!color.get(cur.id)){color.set(cur.id,1);chain.push(cur);cur=byId.get(cur.manager)}if(cur&&color.get(cur.id)===1)throw Error('Circular reporting relationship detected near '+cur.name);for(const q of chain)color.set(q.id,2)}return people}
function orderedPeople(){const kids=new Map();for(const p of state.people){if(!kids.has(p.manager))kids.set(p.manager,[]);kids.get(p.manager).push(p)}const result=[],vis=new Set(),depths=allDepths(state.people),roots=rootsOf(state.people);const todo=[...roots].reverse();while(todo.length){const p=todo.pop();if(vis.has(p.id))continue;vis.add(p.id);result.push(p);const children=kids.get(p.id)||[];for(let i=children.length-1;i>=0;i--)todo.push(children[i])}for(const p of state.people)if(!vis.has(p.id))result.push(p);return {people:result,depths}}
