 if(state.showDept&&h>=87){let by=Math.min(h-13,baseY+20);markup+=`<text x="${contentX}" y="${round(by)}" font-size="${round(deptSize)}" font-weight="600" fill="${a.dark||a.gradient?'#ffffffad':p.accent}" font-family="${esc(font)},Arial,sans-serif">${esc(dept)}</text>`}
