 if(sel){markup+=`<rect class="selection-ring" x="-3" y="-3" width="${w+6}" height="${h+6}" rx="${rounded+3}" fill="none" stroke="${p.accent}" stroke-width="2.6" stroke-dasharray="${d.name==='Minimal'?'5 2':'0'}"/><g class="node-add" data-addto="${esc(person.id)}" role="button" aria-label="Add direct report"><circle cx="${w/2}" cy="${h+18}" r="13" fill="${p.accent}" stroke="white" stroke-width="3"/><text x="${w/2}" y="${h+22.3}" font-size="16" text-anchor="middle" fill="white" font-weight="700">+</text></g>`}
