 let matrixPaths='';if(state.showMatrix){const ids=new Set(shown.map(q=>q.id));matrixPaths=shown.filter(q=>q.secondaryManager&&ids.has(q.secondaryManager)&&q.secondaryManager!==q.manager).map(q=>{const a=l.coords.get(q.secondaryManager),b=l.coords.get(q.id);if(!a||!b)return '';return `<path class="matrix-link" data-matrix="${esc(q.id)}" d="${connectors(a,b,state.layout,'curve')}" fill="none" stroke="${state.matrixColor||'#b369ed'}" stroke-width="${Math.max(1.7,state.lineWidth)}" stroke-linecap="round" stroke-dasharray="4 8" opacity=".83"><title>${esc(q.name)} — dotted-line manager: ${esc(getPerson(q.secondaryManager)?.name||q.secondaryManager)}</title></path>`}).join('')}
