 const stage=$('stage');stage.style.backgroundColor=p.bg;stage.style.backgroundImage=`radial-gradient(${mix(p.accent,'#e7eaf1',.9)} 1px,transparent 1px)`;const svg=$('chartSvg');svg.setAttribute('viewBox',`0 0 ${round(l.width)} ${round(l.height)}`);svg.setAttribute('width',round(l.width));svg.setAttribute('height',round(l.height));svg.innerHTML=defs+`<g class="chart-edges">${paths}${matrixPaths}</g><g class="chart-nodes">${nodes}</g>`;
