function applyZoom(){if(!rendered)return;let z=state.zoom;const svg=$('chartSvg');svg.style.width=(rendered.width*z)+'px';svg.style.height=(rendered.height*z)+'px';$('zoomValue').textContent=Math.round(z*100)+'%'}
function fitChart(silent=false){if(!rendered)return;const stage=$('stage'),w=Math.max(180,stage.clientWidth-125),h=Math.max(150,stage.clientHeight-95),z=Math.min(1.3,w/rendered.width,h/rendered.height);state.zoom=Math.max(.16,Math.min(2.5,z));state.autoFit=true;applyZoom();if(!silent){persist();toast('Chart fitted to viewport')}}
function changeZoom(z){state.zoom=Math.round(Math.max(.15,Math.min(2.5,z))*100)/100;state.autoFit=false;applyZoom();persist()}
function renderPeople(){let {people,depths}=orderedPeople(),q=($('peopleSearch').value||'').toLowerCase().trim();let html='',prior=-1,shown=0;for(const p of people){if(q&&!['name','role','dept','id'].some(k=>p[k].toLowerCase().includes(q)))continue;shown++;if(shown>450)continue;let depth=depths[p.id]||0;if(!q&&depth!==prior){html+=`<div class="person-section-title">${depth===0?'LEADERSHIP':depth===1?'DIRECT REPORTS':depth===2?'TEAM MEMBERS':'LEVEL '+(depth+1)}</div>`;prior=depth}const color=hashColor(p.id+p.dept);html+=`<div class="person-row ${state.selected===p.id?'selected':''}" data-select="${esc(p.id)}"><span class="person-avatar" style="background:${mix(color,'#fff',.88)};color:${color}">${esc(initials(p.name))}</span><span class="identity"><b>${esc(p.name)}</b><small>${esc(shorten(p.role||p.dept,31))}</small></span><span class="more">›</span></div>`}if(shown>450)html+=`<div class="person-section-title">Showing first 450 of ${shown} matching positions — use search or team focus.</div>`;if(!shown)html='<div class="muted" style="padding:15px;font-size:11px">No matching people found.</div>';$('peopleList').innerHTML=html;$('sidePeopleCount').textContent=state.people.length}
function renderStats(){let d=stats();$('statPeople').textContent=d.people;$('statLevels').textContent=d.levels;$('statTeams').textContent=d.teams;$('footerInfo').textContent=`${d.people} positions · ${d.levels} levels`;$('footerLayout').textContent=state.layout==='vertical'?'Top-down':state.layout==='horizontal'?'Left-right':'Radial';$('layoutName').textContent=state.layout==='vertical'?'Top-down hierarchy':state.layout==='horizontal'?'Left-right hierarchy':'Radial hierarchy';$('chartName').value=state.name;$('focusInfo').hidden=!state.focusRoot;$('focusTeamBtn').classList.toggle('tool-selected',!!state.focusRoot);$('focusTeamBtn').innerHTML=state.focusRoot?'↩ <span>All people</span>':'⌗ <span>Focus team</span>'; $('undoBtn').disabled=!undoStack.length;$('redoBtn').disabled=!redoStack.length}
function renderInspector(){const p=getPerson(state.selected);$('selectedInspector').hidden=!p;$('emptyInspector').hidden=!!p;if(!p)return;const {palette:t}=currentTheme();$('inspectorAvatar').textContent=initials(p.name);$('inspectorAvatar').style.background=t.soft;$('inspectorAvatar').style.color=t.accent;$('inspectorName').textContent=p.name;$('inspectorRole').textContent=p.role||p.dept||'Team member';const fields={fieldName:'name',fieldRole:'role',fieldDept:'dept',fieldEmail:'email',fieldLocation:'location',fieldPhone:'phone',fieldGrade:'grade',fieldNotes:'notes'};for(const [id,key] of Object.entries(fields)){if(document.activeElement!==$(id))$(id).value=p[key]||''}const descendants=descendantIds(p.id);let options='<option value="">— Top-level / no manager —</option>';for(const other of orderedPeople().people){if(other.id!==p.id&&!descendants.has(other.id))options+=`<option value="${esc(other.id)}">${esc(other.name)} · ${esc(shorten(other.role,22))}</option>`}$('fieldManager').innerHTML=options;$('fieldManager').value=p.manager||'';$('fieldSecondary').innerHTML='<option value="">— None / single manager —</option>'+orderedPeople().people.filter(x=>x.id!==p.id&&!descendants.has(x.id)).map(x=>`<option value="${esc(x.id)}">${esc(x.name)} · ${esc(shorten(x.role,18))}</option>`).join('');$('fieldSecondary').value=p.secondaryManager||'';$('fieldStatus').value=p.status||'Active';$('inspectorAvatar').innerHTML=p.photo?`<img src="${p.photo}" alt="">`:esc(initials(p.name));$('removePhotoBtn').disabled=!p.photo;$('toggleNodeBtn').textContent=state.collapsed.includes(p.id)?'⊞ Expand':'⊟ Collapse';$('toggleNodeBtn').disabled=!childrenOf(p.id).length}
function renderPresetGallery(){let {palette:p,design:d}=currentTheme();$('activeThemeTitle').textContent=p.name+' · '+d.name+(state.customAccent?' · Custom':'');$('customAccent').value=state.customAccent||p.accent;$('activeSwatches').innerHTML=[p.dark,p.accent,p.accent2,p.soft].map(c=>`<i style="background:${c}"></i>`).join('');const filter=themeFilter,query=($('presetSearch').value||'').toLowerCase().trim();let html='',count=0,eligible=0;for(let idx=0;idx<PRESET_COUNT;idx++){const palette=PALETTES[Math.floor(idx/10)],style=DESIGNS[idx%10];if(filter!=='all'&&style.family!==filter)continue;if(query&&!`${palette.name} ${style.name} ${style.desc}`.toLowerCase().includes(query))continue;eligible++;if(count++>=presetLimit)continue;const isDark=style.name==='Noir',isGradient=style.name==='Gradient',bg=isDark?palette.dark:isGradient?`linear-gradient(135deg,${palette.accent},${palette.accent2})`:'#fff',r=style.radius+'px';html+=`<button class="preset ${state.preset===idx?'chosen':''}" data-preset="${idx}" title="${palette.name} / ${style.name}"><div class="preset-art" style="background:${palette.bg}"><div class="sample-top" style="border-radius:${r};background:${bg};border:1px solid ${palette.accent}"></div><div class="sample-stem"></div><div class="sample-bottom"><i style="border-radius:${r};background:${bg};border:1px solid ${palette.accent}"></i><i style="border-radius:${r};background:${bg};border:1px solid ${palette.accent}"></i></div></div><div class="preset-title">${palette.name} · ${style.name}</div><div class="preset-num">STYLE ${String(idx+1).padStart(3,'0')}</div></button>`}if(!html)html='<p class="muted">No matching styles.</p>';$('presetGallery').innerHTML=html;const more=$('morePresets');more.hidden=eligible<=presetLimit;more.textContent=`Show more (${eligible-presetLimit} remaining) ↓`}
function syncControls(){const fields={horizontalGap:['hGap','hGapValue',' px'],verticalGap:['vGap','vGapValue',' px'],cardWidth:['cardW','cardWValue',' px'],cardHeight:['cardH','cardHValue',' px'],lineWidth:['lineWidth','lineWValue',' px']};for(const [id,[key,out,suffix]] of Object.entries(fields)){$(id).value=state[key];$(out).textContent=state[key]+suffix}$('lineStyle').value=state.lineStyle;$('lineDash').value=state.lineDash;$('lineColor').value=state.lineColor;$('lineArrows').value=state.arrows;$('showDept').checked=state.showDept;$('showAvatars').checked=state.showAvatars;$('snapGrid').checked=state.snapGrid;$('showID').checked=state.showID;$('showMatrix').checked=state.showMatrix!==false;$('chartLegend').classList.toggle('hide-matrix',state.showMatrix===false);$('showStatus').checked=state.showStatus!==false;$('showGrade').checked=state.showGrade!==false;$('matrixColor').value=state.matrixColor||'#b369ed';$('gridSize').value=state.gridSize;$('gridValue').textContent=state.gridSize+' px';$('customBackground').value=state.customBg||currentTheme().palette.bg;$('fontFamily').value=state.fontFamily||'Arial';$('colorMode').value=state.colorMode||'theme';$('pptPageMode').value=state.pptPageMode||'teams';document.querySelectorAll('[data-layout]').forEach(el=>el.classList.toggle('chosen',el.dataset.layout===state.layout))}
