function showPanel(name){activePanel=name;if(innerWidth<=740)$('appShell').classList.add('show-mobile-side');document.querySelectorAll('.rail-btn[data-panel]').forEach(b=>b.classList.toggle('active',b.dataset.panel===name));document.querySelectorAll('.side-panel').forEach(el=>el.classList.toggle('active',el.id==='panel-'+name));}
function selectPerson(id){if(!getPerson(id))return;if(innerWidth<=740){$('appShell').classList.remove('show-mobile-side');$('appShell').classList.add('show-inspector')}state.selected=id;persist();renderPeople();renderInspector();renderSVG()}
function addPerson(manager='',sibling=false){let id=nextId();mutate(()=>{let p=normalizePerson({id,name:'New team member',role:'Job title',dept:manager?getPerson(manager)?.dept||'General':'Executive',manager,email:'',location:'',phone:''});state.people.push(p);state.selected=id;state.collapsed=state.collapsed.filter(x=>x!==manager)},{fit:false});if(innerWidth<=1080){$('appShell').classList.add('show-inspector');$('appShell').classList.remove('show-mobile-side')}else showPanel('people');toast('Person added — update their details on the right')}
function deletePerson(id){const p=getPerson(id);if(!p)return;const children=childrenOf(id);if(!window.confirm(`Remove ${p.name}? ${children.length} direct report(s) will be reassigned to ${p.manager?getPerson(p.manager)?.name||'top level':'top level'}.`))return;mutate(()=>{for(const x of state.people)if(x.manager===id)x.manager=p.manager||'';state.people=state.people.filter(x=>x.id!==id);delete state.manual[id];state.collapsed=state.collapsed.filter(x=>x!==id);for(const x of state.people){if(x.secondaryManager===id)x.secondaryManager=''}state.selected=p.manager&&getPerson(p.manager)?p.manager:(state.people[0]?.id||null)},{fit:true});toast('Person removed and direct reports preserved')}
function toggleCollapse(id){if(!childrenOf(id).length)return;mutate(()=>{if(state.collapsed.includes(id))state.collapsed=state.collapsed.filter(x=>x!==id);else state.collapsed.push(id)},{fit:true})}
function collapseAll(){let candidates=state.people.filter(p=>childrenOf(p.id).length);if(!candidates.length)return;let shouldCollapse=state.collapsed.length!==candidates.length;mutate(()=>{state.collapsed=shouldCollapse?candidates.map(p=>p.id):[]},{fit:true});$('collapseAllBtn').innerHTML=shouldCollapse?'⊞ <span>Expand</span>':'⊟ <span>Collapse</span>'}
