function filename(ext){return ((state.name||'Organization').trim().replace(/[^a-zA-Z0-9 _-]/g,'').replace(/\s+/g,'_').slice(0,70)||'OrgChart')+'.'+ext}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),4000)}
function svgString(){const source=$('chartSvg').cloneNode(true);source.setAttribute('xmlns','http://www.w3.org/2000/svg');source.setAttribute('width',String(Math.ceil(rendered.width)));source.setAttribute('height',String(Math.ceil(rendered.height)));source.style.removeProperty('width');source.style.removeProperty('height');source.querySelectorAll('[data-addto],[data-toggle]').forEach(el=>el.remove());source.querySelectorAll('.selection-ring').forEach(el=>el.remove());const bg=document.createElementNS('http://www.w3.org/2000/svg','rect');bg.setAttribute('width','100%');bg.setAttribute('height','100%');bg.setAttribute('fill',currentTheme().palette.bg);source.insertBefore(bg,source.firstChild);if(typeof v6SvgMetadata==='function')v6SvgMetadata(source);return '<?xml version="1.0" encoding="UTF-8"?>\n'+new XMLSerializer().serializeToString(source)}
