async function imageCanvas(mult=2,white=true){if(!rendered||!state.people.length)throw Error('Add people before exporting.');const z=Math.min(mult,8000/Math.max(rendered.width,rendered.height));let canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.ceil(rendered.width*z));canvas.height=Math.max(1,Math.ceil(rendered.height*z));const ctx=canvas.getContext('2d');if(!ctx)throw Error('Canvas rendering is not available');if(white){ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height)}const blob=new Blob([svgString()],{type:'image/svg+xml;charset=utf-8'}),url=URL.createObjectURL(blob);try{const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('Could not render the SVG in this browser'));img.src=url});ctx.drawImage(img,0,0,canvas.width,canvas.height)}finally{URL.revokeObjectURL(url)}return canvas}
async function canvasBlob(canvas,type='image/png',quality=.96){return new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('Image conversion failed')),type,quality))}
async function exportPNG(){const blob=await canvasBlob(await imageCanvas(2.5));downloadBlob(blob,filename('png'));toast('High-resolution PNG exported')}
function exportJSON(){downloadBlob(new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString(),app:'AviOrg Studio'},null,2)],{type:'application/json'}),filename('json'));toast('Complete editable project saved')}
const HEADERS=['Employee ID','Full Name','Job Title','Department','Manager ID','Email','Location','Phone','Dotted-line Manager ID','Status','Grade','Notes','FTE','Annual Cost','Cost Center','Effective Date','Position ID','Skills / Competencies','Employment Type'];
const COLS=['id','name','role','dept','manager','email','location','phone','secondaryManager','status','grade','notes','fte','annualCost','costCenter','effectiveDate','positionId','skills','employmentType'];
function csvCell(value){let v=String(value??'');return /[",\n\r]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v}
function exportCSV(){const rows=[HEADERS,...state.people.map(p=>COLS.map(k=>p[k]??''))];const csv='\ufeff'+rows.map(row=>row.map(csvCell).join(',')).join('\r\n');downloadBlob(new Blob([csv],{type:'text/csv;charset=utf-8'}),filename('csv'));toast('People directory exported as CSV')}
function excelXml(s){return String(s??'').replace(/[<>&"']/g,ch=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[ch])).replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g,'')}
