function parseCSV(csv){csv=String(csv).replace(/^\ufeff/,'');const rows=[],row=[];let value='',inQuotes=false;for(let i=0;i<csv.length;i++){let ch=csv[i];if(ch==='"'){if(inQuotes&&csv[i+1]==='"'){value+='"';i++}else inQuotes=!inQuotes}else if(ch===','&&!inQuotes){row.push(value);value=''}else if((ch==='\n'||ch==='\r')&&!inQuotes){if(ch==='\r'&&csv[i+1]==='\n')i++;row.push(value);if(row.some(c=>String(c).trim()))rows.push(row.slice());row.length=0;value=''}else value+=ch}if(value.length||row.length){row.push(value);if(row.some(c=>String(c).trim()))rows.push(row.slice())}return rows}
function xmlAll(parent,tag){return Array.from(parent.getElementsByTagNameNS('*',tag))}
function colFromRef(ref){let m=String(ref).match(/^[A-Z]+/i);if(!m)return 0;return [...m[0].toUpperCase()].reduce((v,c)=>v*26+c.charCodeAt(0)-64,0)-1}
async function readExcel(file){if(typeof JSZip==='undefined')throw Error('Spreadsheet parser is unavailable.');let zip=await JSZip.loadAsync(await file.arrayBuffer()),p=new DOMParser();const wbFile=zip.file('xl/workbook.xml');if(!wbFile)throw Error('Invalid Excel workbook: workbook.xml was not found.');let wb=p.parseFromString(await wbFile.async('string'),'text/xml');if(wb.querySelector('parsererror'))throw Error('Invalid Excel workbook XML.');let sheets=xmlAll(wb,'sheet'),chosen=sheets.find(s=>(s.getAttribute('name')||'').toLowerCase().includes('employee'))||sheets[0];if(!chosen)throw Error('No worksheets found.');let rid=chosen.getAttribute('r:id')||chosen.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id');
 const relFile=zip.file('xl/_rels/workbook.xml.rels');let sheetName='xl/worksheets/sheet1.xml';if(relFile&&rid){let rels=p.parseFromString(await relFile.async('string'),'text/xml'),rel=xmlAll(rels,'Relationship').find(e=>e.getAttribute('Id')===rid);if(rel){let target=rel.getAttribute('Target')||'';sheetName=target.startsWith('/')?target.slice(1):target.startsWith('xl/')?target:'xl/'+target;sheetName=sheetName.replace(/\\/g,'/').replace(/^xl\/\.\.\//,'')}}
 let sheetFile=zip.file(sheetName)||zip.file('xl/worksheets/sheet1.xml');if(!sheetFile)throw Error('Could not find the employee worksheet.');let xml=p.parseFromString(await sheetFile.async('string'),'text/xml');if(xml.querySelector('parsererror'))throw Error('Invalid worksheet XML.');let shared=[];const strings=zip.file('xl/sharedStrings.xml');if(strings){const si=p.parseFromString(await strings.async('string'),'text/xml');shared=xmlAll(si,'si').map(node=>xmlAll(node,'t').map(t=>t.textContent||'').join(''))}
 let result=[];for(const row of xmlAll(xml,'row')){let arr=[];for(const cell of xmlAll(row,'c')){let col=colFromRef(cell.getAttribute('r')||'A1'),type=cell.getAttribute('t')||'',v=xmlAll(cell,'v')[0]?.textContent??'',inline=xmlAll(cell,'is')[0];if(type==='s')v=shared[Number(v)]??'';else if(type==='inlineStr'&&inline)v=xmlAll(inline,'t').map(t=>t.textContent||'').join('');else if(type==='b')v=v==='1'?'TRUE':'FALSE';arr[col]=String(v)}if(arr.some(c=>String(c??'').trim()))result.push(arr)}return result}
