function rowsToPeople(rows){if(!rows.length)throw Error('The file is empty.');let headerIndex=-1,mapping={};for(let i=0;i<Math.min(rows.length,12);i++){let m={};(rows[i]||[]).forEach((v,col)=>{let key=headerKey(v);for(const [field,aliases] of Object.entries(ALIASES))if(aliases.some(a=>headerKey(a)===key))m[field]=col});if(m.id!==undefined&&m.name!==undefined){headerIndex=i;mapping=m;break}}if(headerIndex===-1)throw Error('Could not find Employee ID and Full Name headers. Download our Excel template to see the required format.');let people=[];for(const row of rows.slice(headerIndex+1)){const p={};for(const key of COLS)p[key]=mapping[key]!==undefined?String(row[mapping[key]]??'').trim():'';if(!p.id&&!p.name)continue;if(!p.id||!p.name)throw Error('A row is missing Employee ID or Full Name.');people.push(p)}if(!people.length)throw Error('No employee records were found below the header.');const byNames=new Map();for(const p of people){let name=p.name.toLowerCase();if(!byNames.has(name))byNames.set(name,p.id);else byNames.set(name,null)}for(const p of people){if(p.manager&&!people.some(x=>x.id===p.manager)){let nameId=byNames.get(p.manager.toLowerCase());if(nameId)p.manager=nameId}}return validPeople(people.map(normalizePerson))}
async function readImport(file){if(!file)throw Error('Select an Excel, CSV, AviOrg PPTX or project JSON file.');let lower=file.name.toLowerCase();if(lower.endsWith('.xlsx'))return {people:rowsToPeople(await readExcel(file))};if(lower.endsWith('.csv'))return {people:rowsToPeople(parseCSV(await file.text()))};if(lower.endsWith('.pptx')){
   const pack=await JSZip.loadAsync(await file.arrayBuffer()),entry=pack.file('structura/project.xml');
   if(!entry)return v6ReadGenericPptx(file,pack);
   const xml=new DOMParser().parseFromString(await entry.async('string'),'text/xml');
   if(xml.querySelector('parsererror'))throw Error('Invalid embedded chart source');
   const payload=xml.getElementsByTagName('structuraSource')[0]?.textContent;
   if(!payload)throw Error('The PowerPoint source data is empty');
   const project=JSON.parse(payload);
   if(!Array.isArray(project.people)||project.people.length>10000)throw Error('Invalid or oversized embedded organization data');
   return {people:validPeople(project.people.map(normalizePerson)),project};
  }
  if(lower.endsWith('.vsdx'))return v6ReadVisio(file);if(lower.endsWith('.svg'))return v6ReadSvg(file);if(lower.endsWith('.pdf'))return v6ReadPdf(file);if(lower.match(/\.(png|jpg|jpeg|webp)$/))throw Error('Raster images need manual tracing: open Universal Import > Reference image and trace employee cards.');if(lower.endsWith('.json')){let json=JSON.parse(await file.text());if(!Array.isArray(json.people))throw Error('This JSON does not contain a people array.');return {people:validPeople(json.people.map(normalizePerson)),project:json}}throw Error('Unsupported file type. Use .xlsx, .csv, AviOrg .pptx or .json')}
function fieldDifference(a,b){const fields=['name','role','dept','manager','secondaryManager','status','grade','email','location','phone','notes','fte','annualCost','costCenter','effectiveDate','positionId','skills','employmentType'];return fields.filter(k=>String(k==='status'?(a[k]||'Active'):(a[k]??''))!==String(k==='status'?(b[k]||'Active'):(b[k]??'')))}
function comparePeople(before,after){const old=new Map(before.map(p=>[p.id,p])),next=new Map(after.map(p=>[p.id,p])),result={added:[],updated:[],removed:[],unchanged:[]};for(const p of after){if(!old.has(p.id))result.added.push({person:p});else{const changed=fieldDifference(old.get(p.id),p);if(changed.length)result.updated.push({person:p,from:old.get(p.id),fields:changed});else result.unchanged.push({person:p})}}for(const p of before)if(!next.has(p.id))result.removed.push({person:p});return result}
function proposedPeople(incoming,mode){const incomingClean=incoming.map(normalizePerson),existing=state.people.map(normalizePerson);if(mode==='replace')return incomingClean;if(mode==='add'){const ids=new Set(existing.map(p=>p.id));const conflict=incomingClean.find(p=>ids.has(p.id));if(conflict)throw Error('Employee ID '+conflict.id+' already exists — use Update existing or Replace');return [...existing,...incomingClean]}if(mode==='upsert'){const incomingMap=new Map(incomingClean.map(p=>[p.id,p]));return [...existing.map(p=>incomingMap.get(p.id)||p),...incomingClean.filter(p=>!existing.some(x=>x.id===p.id))]}throw Error('Choose a supported import mode')}
function validateCandidate(people){if(!people.length)throw Error('Chart cannot be empty');validPeople(people);const ids=new Set(people.map(p=>p.id));let missing=people.filter(p=>p.manager&&!ids.has(p.manager));if(missing.length)throw Error('Missing primary manager '+missing[0].manager+' for '+missing[0].name+' — correct the Excel workbook or choose Update existing');const bad=people.filter(p=>p.secondaryManager&&!ids.has(p.secondaryManager));if(bad.length)throw Error('Missing dotted-line manager '+bad[0].secondaryManager+' for '+bad[0].name);return people}
function importPeople(people,mode='replace',project=null){if(typeof mode==='boolean')mode=mode?'add':'replace';const proposed=validateCandidate(proposedPeople(people,mode)),ids=new Set(proposed.map(p=>p.id));mutate(()=>{if(project&&mode==='replace'){const safeKeys=['name','preset','customAccent','customBg','fontFamily','colorMode','snapGrid','gridSize','showID','showMatrix','showStatus','showGrade','matrixColor','pptPageMode','layout','hGap','vGap','cardW','cardH','lineStyle','lineDash','lineWidth','lineColor','arrows','showDept','showAvatars','collapsed','manual','baseline','v4','v5','v6'];for(const key of safeKeys)if(project[key]!==undefined)state[key]=deep(project[key])}state.people=proposed;state.selected=ids.has(state.selected)?state.selected:proposed[0].id;state.collapsed=state.collapsed.filter(id=>ids.has(id));state.manual=Object.fromEntries(Object.entries(state.manual||{}).filter(([k])=>ids.has(k)));state.focusRoot=ids.has(state.focusRoot)?state.focusRoot:'';state.zoom=1},{fit:true});toast(`${people.length} Excel rows applied using ${mode==='upsert'?'update & add':mode} mode`)}

function openModal(title,eyebrow,body,large=false){$('modalTitle').textContent=title;$('modalEyebrow').textContent=eyebrow;$('modalBody').innerHTML=body;$('modal').classList.toggle('large',large);$('modalBackdrop').hidden=false;setTimeout(()=>$('modalClose').focus(),30)}
