function showImport(){openModal('Import your organization','EXCEL / CSV / JSON',`<div class="dropzone" id="dropzone" tabindex="0" role="button"><span class="drop-icon">↥</span><h3>Drop your spreadsheet here</h3><p>or click to choose a .xlsx, .csv, or AviOrg .json file</p></div><div style="display:flex;gap:15px;align-items:center;margin-top:18px"><label style="font-size:11px;color:#61708a"><input type="radio" name="importMode" value="replace" checked> Replace current chart</label><label style="font-size:11px;color:#61708a"><input type="radio" name="importMode" value="merge"> Merge into chart</label></div><h4 style="font-size:12px;margin:22px 0 8px">Expected Excel columns</h4><div style="overflow:auto"><table class="sample-table"><thead><tr><th>Employee ID</th><th>Full Name</th><th>Job Title</th><th>Department</th><th>Manager ID</th></tr></thead><tbody><tr><td>E001</td><td>Alex Morgan</td><td>CEO</td><td>Executive</td><td><em>blank</em></td></tr><tr><td>E002</td><td>Priya Shah</td><td>COO</td><td>Operations</td><td>E001</td></tr></tbody></table></div><p style="font-size:11px;color:#8792a7;line-height:1.7">Additional supported columns: Email, Location, Phone, Dotted-line Manager ID, Status, Grade, Notes. Every person needs a unique Employee ID; Manager ID points to another employee's ID. Empty Manager ID indicates a top-level employee.</p><div class="modal-actions"><button class="secondary-btn" id="downloadTemplateModal">↓ Download Excel template</button><button class="primary-btn" id="chooseImportFile">Choose file</button></div>`)}
function bulkRow(p,idx){return `<tr data-oldid="${esc(p.id||'')}"><td>${idx+1}</td>${COLS.map(k=>`<td><input data-col="${k}" value="${esc(p[k]||'')}" placeholder="${k==='id'?'E000':k==='name'?'Full name':k==='manager'?'Manager ID':k}" title="${esc(k)}"/></td>`).join('')}<td><button class="bulk-delete" title="Remove row">×</button></td></tr>`}
function showBulk(){const people=orderedPeople().people;openModal('Edit your directory','BULK PEOPLE EDITOR',`<div class="bulk-topline"><span>Update multiple records, job titles and reporting lines at once. Changes apply when you click Save.</span><button class="secondary-btn" id="bulkAdd">＋ Add row</button></div><div class="bulk-table-wrap"><table class="bulk-table" id="bulkTable"><thead><tr><th>#</th>${HEADERS.map(h=>`<th>${h}</th>`).join('')}<th></th></tr></thead><tbody>${people.map(bulkRow).join('')}</tbody></table></div><div class="modal-actions"><button class="secondary-btn" id="bulkCancel">Cancel</button><button class="primary-btn" id="bulkSave">Save ${people.length} people</button></div>`,true)}
function saveBulk(){let rows=Array.from(document.querySelectorAll('#bulkTable tbody tr')),people=[],rename=new Map();for(const tr of rows){let p={};for(const input of tr.querySelectorAll('input[data-col]'))p[input.dataset.col]=input.value.trim();if(!p.id&&!p.name)continue;let old=tr.dataset.oldid;if(old&&old!==p.id)rename.set(old,p.id);people.push({...getPerson(old||p.id),...p})}for(const p of people){if(rename.has(p.manager))p.manager=rename.get(p.manager);if(rename.has(p.secondaryManager))p.secondaryManager=rename.get(p.secondaryManager)}people=people.map(normalizePerson);validPeople(people);mutate(()=>{state.people=people;state.selected=people.some(p=>p.id===state.selected)?state.selected:people[0].id;state.collapsed=[];state.manual={}},{fit:true});closeModal();toast('Bulk directory changes applied')}
function newChart(){if(!confirm('Start a new blank organization chart? Export a JSON project first if you want to keep an independent backup.'))return;mutate(()=>{state.people=[];state.selected=null;state.collapsed=[];state.manual={};state.baseline=null;if(state.v4){state.v4.reviews=[];state.v4.snapshots=[];state.v4.locks=[];state.v4.audit=[]}state.name='Untitled organization chart'},{fit:true});toast('New blank chart created')}
function showHelp(){openModal('Make the most of AviOrg','HOW TO USE',`<div class="help-section"><h4>Build your organization</h4><p>Click a card to select it. Edit fields in the right-hand inspector. Use <b>Add direct report</b>, <b>Sibling</b>, or the purple ＋ below a selected card to grow your hierarchy. Double-click a card to add a new direct report. Drag cards anywhere to adjust their positions.</p><h4>500 visual styles</h4><p>Open <b>Styles</b> on the left to browse 50 palettes × 10 card designs. Use <b>Layout</b> to change orientation, sibling spacing, hierarchy spacing, card size, connector routing and line styles.</p><h4>Matrix reporting, vacancies and scenarios</h4><p>Set an additional dotted-line manager, position status and grade in the Properties panel. Save a baseline under Plan, make changes and compare or restore. Excel imports show new, updated, missing and unchanged rows before committing.</p><h4>AviOrg Pro 4.0</h4><p><b>Editor</b> supports Ctrl/⌘ multi-select, alignment, locking and reusable design kits. <b>AI Studio</b> turns pasted indented outlines into charts offline; optional local Ollama requires your own model server. <b>Workforce</b> tracks FTE, position cost, departments and dated snapshots. <b>Reviews</b> exchanges JSON review packets with colleagues offline.</p><h4>Import and export</h4><p>Upload a formatted <b>.xlsx</b> or <b>.csv</b> file (Employee ID, Full Name, Manager ID), or restore a saved <b>.json</b> project. Export as editable PowerPoint, Excel, PDF, SVG, PNG, CSV, and JSON.</p><h4>AviOrg Pro 6.0</h4><p><b>Chart Importer</b> restores source-backed SVG/PPTX and offers low-confidence PowerPoint/Visio shape extraction. Text-based PDFs can be converted from reviewable outlines; raster images use manual tracing. <b>Layout Doctor</b> scans for overlaps and suggests repair. <b>Office Refresh</b> compares a new spreadsheet to the local chart and safely refreshes editable slides. <b>People Analytics</b> adds FTE/cost/department measures. <b>Performance</b> caps rendered cards while retaining all data.</p><h4>Keyboard shortcuts</h4><p><kbd>Ctrl</kbd> + <kbd>Z</kbd> Undo &nbsp;&nbsp; <kbd>Ctrl</kbd> + <kbd>Y</kbd> Redo &nbsp;&nbsp; <kbd>Delete</kbd> Remove selected person &nbsp;&nbsp; <kbd>Esc</kbd> Close dialog</p><h4>Privacy and autosave</h4><p>Employee data is processed locally in your browser and automatically stored in browser storage. No data is uploaded to a server by default. A local Ollama request is only sent when you explicitly press Generate with local model. Download a JSON project for an independent backup.</p></div>`)}

function organizationInsights(people=state.people){const ids=new Set(people.map(p=>p.id)),counts=new Map(),managers=new Map();for(const p of people){counts.set(p.dept||'Unassigned',(counts.get(p.dept||'Unassigned')||0)+1);if(p.manager&&ids.has(p.manager))managers.set(p.manager,(managers.get(p.manager)||0)+1)}const issues=[];for(const p of people){if(p.manager&&!ids.has(p.manager))issues.push(`${p.name}: manager ID ${p.manager} is not in this chart`);if(!p.role)issues.push(`${p.name}: job title is missing`);if(!p.dept)issues.push(`${p.name}: department is missing`);if(p.secondaryManager&&!ids.has(p.secondaryManager))issues.push(`${p.name}: dotted-line manager ${p.secondaryManager} is not in this chart`);if(p.secondaryManager&&p.secondaryManager===p.manager)issues.push(`${p.name}: dotted-line manager duplicates primary manager`)}let maxSpan=Math.max(0,...managers.values());return {departments:[...counts].sort((a,b)=>b[1]-a[1]),managers:[...managers].sort((a,b)=>b[1]-a[1]),issues,maxSpan,unassigned:people.filter(p=>!p.manager).length,levels:Object.values(allDepths(people)).length?Math.max(...Object.values(allDepths(people)))+1:0}}
function renderInsights(){const i=organizationInsights(),n=state.people.length,v=state.people.filter(p=>p.status==='Vacant').length,planned=state.people.filter(p=>p.status==='Planned').length,matrix=state.people.filter(p=>p.secondaryManager&&p.secondaryManager!==p.manager).length;$('insightCards').innerHTML=`<div><b>${n}</b><span>Total positions</span></div><div><b>${n-v-planned}</b><span>Filled positions</span></div><div><b>${v}</b><span>Vacancies</span></div><div><b>${planned}</b><span>Planned roles</span></div><div><b>${matrix}</b><span>Dotted-line links</span></div><div><b>${i.maxSpan}</b><span>Largest team</span></div>`;$('departmentInsights').innerHTML=i.departments.map(([name,num])=>`<div class="insight-row"><div><b>${esc(name)}</b><small>${num} people · ${n?Math.round(num/n*100):0}%</small></div><div class="insight-track"><i style="width:${n?num/n*100:0}%;background:${hashColor(name)}"></i></div></div>`).join('')||'<p class="muted">No departments yet.</p>';$('managerInsights').innerHTML=i.managers.slice(0,7).map(([id,num])=>`<div class="manager-row"><span>${esc(shorten(getPerson(id)?.name||id,22))}</span><strong>${num} reports</strong></div>`).join('')||'<p class="muted">No reporting lines yet.</p>';$('qualityInsights').innerHTML=i.issues.length?`<div class="quality-warning">⚠ ${i.issues.length} data issue(s)<ul>${i.issues.slice(0,6).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:'<div class="quality-ok">✓ Reporting data looks complete</div>'}
function exportInsightsCSV(){const info=organizationInsights();let rows=[['Metric','Value'],['Total positions',state.people.length],['Filled positions',state.people.filter(p=>p.status==='Active').length],['Vacancies',state.people.filter(p=>p.status==='Vacant').length],['Planned positions',state.people.filter(p=>p.status==='Planned').length],['Matrix links',state.people.filter(p=>p.secondaryManager&&p.secondaryManager!==p.manager).length],['Levels',info.levels],['Departments',info.departments.length],['Largest manager span',info.maxSpan],['Root positions',info.unassigned],[],['Department','Headcount'],...info.departments,[],['Manager ID','Direct reports'],...info.managers,[],['Data issues'],...info.issues.map(v=>[v])];downloadBlob(new Blob(['\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),'AviOrg_Organization_Insights.csv');toast('Organization insights downloaded')}
function tidyCanvas(){mutate(()=>{state.manual={};state.collapsed=[];state.focusRoot='';state.autoFit=true},{fit:true});toast('Layout optimized and manual offsets cleared')}
function toggleFocus(){if(state.focusRoot){mutate(()=>{state.focusRoot='';state.autoFit=true},{fit:true});toast('Showing full organization')}else if(state.selected){mutate(()=>{state.focusRoot=state.selected;state.autoFit=true},{fit:true});toast('Focused on selected reporting team')}}
function beginRelink(){if(!state.selected){toast('Select a person to move first',true);return}reparentMode=!reparentMode;$('changeManagerBtn').classList.toggle('tool-selected',reparentMode);$('changeManagerBtn').innerHTML=reparentMode?'× <span>Cancel relink</span>':'⇄ <span>Relink</span>';toast(reparentMode?'Now click the new manager (or click Relink to cancel)':'Relink cancelled')}
function relinkTo(target){const source=state.selected;if(!source||!getPerson(target)){reparentMode=false;return}if(source===target||descendantIds(source).has(target)){toast('Cannot assign a person to themselves or their own descendant',true);return}mutate(()=>{getPerson(source).manager=target;state.manual={};state.collapsed=[];state.focusRoot='';state.selected=source},{fit:true});reparentMode=false;$('changeManagerBtn').classList.remove('tool-selected');$('changeManagerBtn').innerHTML='⇄ <span>Relink</span>';toast(`${getPerson(source)?.name} now reports to ${getPerson(target)?.name}`)}
let pendingImport=null;
function reviewImport(result,filename){pendingImport=result;const i=organizationInsights(result.people),diff=comparePeople(state.people,result.people);const table=result.people.slice(0,8).map(p=>{let older=state.people.find(x=>x.id===p.id),changed=older?fieldDifference(older,p):[];return `<tr><td>${esc(p.id)}</td><td>${esc(p.name)}</td><td>${esc(p.role)}</td><td>${esc(p.secondaryManager||'—')}</td><td>${esc(p.status||'Active')}</td><td><span class="change-tag ${older?(changed.length?'updated':'same'):'added'}">${older?(changed.length?'UPDATED':'UNCHANGED'):'NEW'}</span></td></tr>`}).join('');openModal((/\.(?:xlsx|csv)$/i.test(filename)?'Review Excel changes':'Review imported chart'),'SAFE DATA IMPORT',`<p class="muted" style="font-size:11px">Source: <b>${esc(filename)}</b>. Compare incoming records before applying any changes.</p>${result.confidence?`<div class="v6-note warn"><b>Import confidence: ${esc(result.confidence)}</b><small>${esc(result.note||'Verify names and all reporting lines before approval.')}</small></div>`:''}<div class="import-summary"><div><b>${diff.added.length}</b><span>New rows</span></div><div><b>${diff.updated.length}</b><span>Changed rows</span></div><div><b>${diff.removed.length}</b><span>Not in file</span></div><div><b>${i.issues.length}</b><span>Warnings</span></div></div><div class="import-choice review-choices"><label><input type="radio" name="reviewMode" value="upsert" checked> <b>Update & add</b><small>Keep rows missing from file</small></label><label><input type="radio" name="reviewMode" value="replace"> <b>Replace entire chart</b><small>Remove rows missing from file</small></label><label><input type="radio" name="reviewMode" value="add"> <b>Add new only</b><small>Requires unique IDs</small></label></div><div id="importModeEffect" class="import-mode-effect"></div><div class="bulk-table-wrap"><table class="sample-table"><thead><tr><th>ID</th><th>Full name</th><th>Job title</th><th>Dotted manager</th><th>Status</th><th>Change</th></tr></thead><tbody>${table}</tbody></table></div>${i.issues.length?`<div class="quality-warning" style="margin-top:13px">⚠ Incoming file has ${i.issues.length} warning(s). Some may be resolved by Update & add. <ul>${i.issues.slice(0,5).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}<div class="modal-actions"><button class="secondary-btn" id="reviewCancel">Cancel</button><button class="primary-btn" id="reviewApprove">Apply reviewed changes</button></div>`,true);renderImportImpact()}
function renderImportImpact(){if(!pendingImport)return;const mode=document.querySelector('input[name="reviewMode"]:checked')?.value||'upsert',el=$('importModeEffect');if(!el)return;try{const people=validateCandidate(proposedPeople(pendingImport.people,mode)),diff=comparePeople(state.people,people);el.innerHTML=`<span class="effect-good">✓ Ready to apply</span> &nbsp; <b>+${diff.added.length} new</b> · <b>${diff.updated.length} updated</b> · <b>${diff.removed.length} removed</b> · ${diff.unchanged.length} unchanged <small>Existing manual card positions are retained for matching IDs.</small>`;$('reviewApprove').disabled=false}catch(e){el.innerHTML=`<span class="effect-error">⚠ ${esc(e.message)}</span>`;$('reviewApprove').disabled=true}}


function applyDensity(mode){mutate(()=>{if(mode==='compact'){state.cardW=176;state.cardH=88;state.hGap=15;state.vGap=55}else{state.cardW=234;state.cardH=112;state.hGap=54;state.vGap=104}state.manual={};state.autoFit=true},{fit:true});toast((mode==='compact'?'Compact':'Spacious')+' layout applied')}
/* ----------------------------- SCENARIO PLANNER ----------------------------- */
function baselineDate(){try{return new Date(state.baseline?.timestamp).toLocaleString()}catch(e){return 'Saved snapshot'}}
function captureBaseline(){mutate(()=>{state.baseline={name:state.name,timestamp:new Date().toISOString(),people:deep(state.people)}});toast('Baseline saved. You can now experiment with changes.');showPanel('scenarios')}
function scenarioChanges(){return state.baseline?.people?comparePeople(state.baseline.people,state.people):null}
function renderScenarios(){const el=$('scenarioSummary');if(!el)return;const d=scenarioChanges();$('compareScenarioBtn').disabled=!d;$('exportScenarioBtn').disabled=!d;$('restoreBaselineBtn').disabled=!d;if(!d){el.innerHTML='<div class="scenario-empty">No saved baseline yet.<br><small>Capture a snapshot to compare future organizational changes.</small></div>';return}const {added,updated,removed}=d;const notable=updated.slice(0,6).map(x=>`<div class="scenario-line"><b>${esc(shorten(x.person.name,24))}</b><small>${esc(x.fields.join(', '))}</small></div>`).join('');el.innerHTML=`<div class="scenario-stamp">BASELINE SAVED · ${esc(baselineDate())}</div><div class="scenario-metrics"><div><b>${added.length}</b><span>Added</span></div><div><b>${updated.length}</b><span>Changed</span></div><div><b>${removed.length}</b><span>Removed</span></div></div>${notable||'<div class="quality-ok">✓ No changes from the saved baseline</div>'}`}
function showScenarioReport(){const d=scenarioChanges();if(!d){toast('Capture a baseline first',true);showPanel('scenarios');return}const rows=[...d.added.map(x=>({type:'Added',id:x.person.id,name:x.person.name,detail:x.person.role})),...d.updated.map(x=>({type:'Changed',id:x.person.id,name:x.person.name,detail:x.fields.map(k=>`${k}: ${x.from[k]||'—'} → ${x.person[k]||'—'}`).join(' | ')})),...d.removed.map(x=>({type:'Removed',id:x.person.id,name:x.person.name,detail:x.person.role}))];openModal('Scenario comparison','BEFORE / AFTER',`<div class="import-summary"><div><b>${state.baseline.people.length}</b><span>Baseline positions</span></div><div><b>${state.people.length}</b><span>Current positions</span></div><div><b>${d.updated.length}</b><span>Changed</span></div><div><b>${d.added.length+d.removed.length}</b><span>Added / removed</span></div></div><div class="bulk-table-wrap"><table class="sample-table" style="width:100%"><thead><tr><th>Change</th><th>ID</th><th>Name</th><th>Details</th></tr></thead><tbody>${rows.slice(0,200).map(x=>`<tr><td><span class="change-tag ${x.type.toLowerCase()}">${x.type}</span></td><td>${esc(x.id)}</td><td>${esc(x.name)}</td><td>${esc(x.detail)}</td></tr>`).join('')||'<tr><td colspan="4">No differences detected.</td></tr>'}</tbody></table></div><p class="muted" style="font-size:11px;margin-top:13px">All changes are editable in your current project. Use Plan → Restore baseline to revert.</p><div class="modal-actions"><button class="secondary-btn" id="closeScenarioReport">Close</button><button class="primary-btn" id="exportScenarioInModal">Export change log CSV</button></div>`,true)}
function exportScenarioCSV(){const d=scenarioChanges();if(!d){toast('Capture a baseline first',true);return}let rows=[['Change','Employee ID','Name','Field','Before','After']];for(const x of d.added)rows.push(['Added',x.person.id,x.person.name,'Position','','Created']);for(const x of d.removed)rows.push(['Removed',x.person.id,x.person.name,'Position','Present','Removed']);for(const x of d.updated)for(const k of x.fields)rows.push(['Updated',x.person.id,x.person.name,k,x.from[k]||'',x.person[k]||'']);downloadBlob(new Blob(['\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),'AviOrg_Scenario_Changes.csv');toast('Scenario change log exported')}
function restoreBaseline(){if(!state.baseline?.people)return;if(!confirm('Restore the baseline? Your current changes will be replaced (Undo remains available).'))return;mutate(()=>{state.people=deep(state.baseline.people).map(normalizePerson);state.name=state.baseline.name||state.name;state.manual={};state.collapsed=[];state.selected=state.people[0]?.id||null},{fit:true});toast('Baseline restored')}
