function updatePerson(field,value){if(!getPerson(state.selected))return;if(getPerson(state.selected)[field]===value)return;if(['manager','secondaryManager'].includes(field)&&(value===state.selected||descendantIds(state.selected).has(value))){toast('Cannot select this reporting relationship',true);return}mutate(()=>{const p=getPerson(state.selected);p[field]=value;if(field==='manager')state.manual={}},{fit:field==='manager'})}
